BEGIN;
INSERT INTO customer(first_name,last_name,email,phone,password) VALUES('G05','Probe','g05-a4@example.invalid','000','non-login-test-marker') RETURNING customer_id AS cid \gset
INSERT INTO staff(first_name,last_name,email,role,password) VALUES('G05','Probe','g05-staff@example.invalid','staff','non-login-test-marker') RETURNING staff_id AS sid \gset
INSERT INTO menu_item(item_name,category,price) VALUES('G05 A4 probe','Probe',8.75) RETURNING menu_item_id AS mid \gset
INSERT INTO restaurant_table(table_number,capacity) VALUES(900001,4) RETURNING table_id AS tid \gset
INSERT INTO orders(customer_id) VALUES(:cid) RETURNING order_id AS oid \gset
INSERT INTO order_item(order_id,menu_item_id,quantity,unit_price,subtotal) VALUES(:oid,:mid,2,8.75,17.50);
INSERT INTO payment(order_id,payment_method,amount) VALUES(:oid,'cash',17.50);
INSERT INTO reservation(customer_id,table_id,reservation_date,reservation_time,number_of_guests) VALUES(:cid,:tid,'2099-01-01','10:00',2) RETURNING reservation_id AS rid \gset
UPDATE customer SET first_name='G05 updated' WHERE customer_id=:cid;
UPDATE staff SET first_name='G05 updated' WHERE staff_id=:sid;
UPDATE menu_item SET price=10 WHERE menu_item_id=:mid;
UPDATE restaurant_table SET status='reserved' WHERE table_id=:tid;
UPDATE orders SET order_status='confirmed' WHERE order_id=:oid;
UPDATE payment SET payment_status='paid' WHERE order_id=:oid;
UPDATE reservation SET reservation_status='cancelled' WHERE reservation_id=:rid;
SELECT total_amount AS captured_total FROM orders WHERE order_id=:oid;
SET CONSTRAINTS ALL IMMEDIATE;
DELETE FROM reservation WHERE reservation_id=:rid;
DELETE FROM restaurant_table WHERE table_id=:tid;
DELETE FROM staff WHERE staff_id=:sid;
ROLLBACK;

SELECT version(),current_database();
SELECT rolname,rolcanlogin,rolsuper,rolcreatedb,rolcreaterole,rolreplication,rolbypassrls,rolinherit FROM pg_roles WHERE rolname LIKE 'rors_%' ORDER BY 1;
SELECT a.rolname AS member,b.rolname AS parent,m.admin_option,m.inherit_option,m.set_option FROM pg_auth_members m JOIN pg_roles a ON a.oid=m.member JOIN pg_roles b ON b.oid=m.roleid WHERE a.rolname LIKE 'rors_%';
SELECT datname,pg_get_userbyid(datdba),datacl FROM pg_database ORDER BY datname;
SELECT nspname,nspacl FROM pg_namespace WHERE nspname='public';
SELECT c.relname,c.relkind,pg_get_userbyid(c.relowner) AS owner,c.relacl FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relkind IN('r','S','v') ORDER BY c.relname;
SELECT proname,pg_get_userbyid(proowner),prosecdef,proacl FROM pg_proc p WHERE pronamespace='public'::regnamespace AND NOT EXISTS(SELECT 1 FROM pg_depend d WHERE d.classid='pg_proc'::regclass AND d.objid=p.oid AND d.deptype='e') ORDER BY proname;
SELECT t.tgrelid::regclass,t.tgname,t.tgenabled FROM pg_trigger t WHERE NOT t.tgisinternal ORDER BY 1,2;
SELECT extname,extversion FROM pg_extension ORDER BY 1;
SELECT defaclrole::regrole,defaclobjtype,defaclacl FROM pg_default_acl;
SELECT conrelid::regclass,conname,pg_get_constraintdef(oid) FROM pg_constraint WHERE connamespace='public'::regnamespace ORDER BY 1,2;
SELECT 'customer',count(*) FROM customer UNION ALL SELECT 'staff',count(*) FROM staff UNION ALL SELECT 'menu_item',count(*) FROM menu_item UNION ALL SELECT 'restaurant_table',count(*) FROM restaurant_table UNION ALL SELECT 'orders',count(*) FROM orders UNION ALL SELECT 'order_item',count(*) FROM order_item UNION ALL SELECT 'reservation',count(*) FROM reservation UNION ALL SELECT 'payment',count(*) FROM payment;
SELECT to_regclass('g05_future_probe') IS NULL AS probe_table_removed,to_regprocedure('g05_future_function()') IS NULL AS probe_function_removed;
